import{_ as r,o as l,c as n,a5 as a,j as t}from"./chunks/framework.QWVCgkrI.js";const u=JSON.parse('{"title":"PagedAttention — LLMのKVキャッシュを、連続した領域に置かなくてよいのはなぜか","description":"","frontmatter":{"title":"PagedAttention — LLMのKVキャッシュを、連続した領域に置かなくてよいのはなぜか","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"algorithms","summary":"長さの異なる2リクエストでKVの連続予約とブロック割り当てを比べ、論理位置からの参照、終了後の再利用、共有とコピーオンライトを追う。","aliases":["PagedAttention","Paged Attention","ページドアテンション","KVブロック","KV block table"],"verification":"PagedAttentionの原論文、vLLMとLinuxの公式文書に照合し、WindowsのPython 3.12.4で確保枠・参照位置・再割り当ての説明例を検算（2026-11-21）"}},"headers":[],"relativePath":"algorithms/paged-attention.md","filePath":"algorithms/paged-attention.md"}'),i={name:"algorithms/paged-attention.md"};function o(s,e,d,h,g,p){return l(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="pagedattention-—-llmのkvキャッシュを、連続した領域に置かなくてよいのはなぜか" tabindex="-1">PagedAttention — LLMのKVキャッシュを、連続した領域に置かなくてよいのはなぜか <a class="header-anchor" href="#pagedattention-—-llmのkvキャッシュを、連続した領域に置かなくてよいのはなぜか" aria-label="Permalink to &quot;PagedAttention — LLMのKVキャッシュを、連続した領域に置かなくてよいのはなぜか&quot;">​</a></h1><p>二人が同じLLMを使い、一方は短い返事を、もう一方は詳しい説明を待っているとします。推論サーバーは、処理したトークンのKeyとValueを <a href="/study/algorithms/kv-cache.html">KVキャッシュ</a> に保存します。両方に最大長ぶんの領域を先に取り置くと、まだ使っていない枠があっても、ほかのリクエストに渡せません。<strong>PagedAttention</strong>は、KVを離れたブロックに置けるようにし、Attentionの計算でそれぞれの置き場所を参照する方法です。<a href="https://arxiv.org/abs/2309.06180" target="_blank" rel="noreferrer">Kwonらの原論文 §3–4</a></p><h2 id="この記事で分かること" tabindex="-1">この記事で分かること <a class="header-anchor" href="#この記事で分かること" aria-label="Permalink to &quot;この記事で分かること&quot;">​</a></h2><p>最大長ぶんの連続予約と、必要なブロックだけを割り当てる方式で、同じ2リクエストが使う枠を比べられます。トークン位置からKVを探す流れと、再利用や共有が同時処理にどう効くかを説明できます。</p><h2 id="最大長を予約する場合と、使う枠だけを割り当てる場合" tabindex="-1">最大長を予約する場合と、使う枠だけを割り当てる場合 <a class="header-anchor" href="#最大長を予約する場合と、使う枠だけを割り当てる場合" aria-label="Permalink to &quot;最大長を予約する場合と、使う枠だけを割り当てる場合&quot;">​</a></h2><p>同じモデルでリクエストAとBを1列ずつ処理します。入力と生成を合わせた上限は各16トークンです。ある時点で、入力を含む<strong>処理済みのトークン</strong>はAが9個、Bが6個とします。1枠は1位置ぶんのKVです。両者は1枠あたり同じ容量を使い、キャッシュは共有しません。管理情報や先回りの割り当ては数えません。</p><ul><li><strong>連続予約</strong>では、各列に16枠の連続したGPUバッファの範囲を先に割り当てます。実際に何枠使っているかにかかわらず、各範囲を他の列から使えない方式を想定します。</li><li><strong>ブロック割り当て</strong>では、推論エンジンがKV用に確保した領域を、たとえば4枠ずつに区切っておきます。列に割り当てるのは必要になったブロックだけです。Aの9枠には3ブロック、Bの6枠には2ブロックが要ります。<a href="https://arxiv.org/html/2309.06180#S4.SS2" target="_blank" rel="noreferrer">Kwonらの原論文 §3.1・§4.2–4.3</a></li></ul><table tabindex="0"><thead><tr><th>列</th><th style="text-align:right;">使用中の枠</th><th style="text-align:right;">連続予約</th><th style="text-align:right;">ブロック割り当て</th><th style="text-align:right;">最終ブロックの未使用枠</th></tr></thead><tbody><tr><td>A</td><td style="text-align:right;">9</td><td style="text-align:right;">16</td><td style="text-align:right;">12</td><td style="text-align:right;">3</td></tr><tr><td>B</td><td style="text-align:right;">6</td><td style="text-align:right;">16</td><td style="text-align:right;">8</td><td style="text-align:right;">2</td></tr><tr><td>合計</td><td style="text-align:right;">15</td><td style="text-align:right;">32</td><td style="text-align:right;">20</td><td style="text-align:right;">5</td></tr></tbody></table><p>連続予約では、32枠のうち17枠が未使用のまま各列に取り置かれています。ブロック方式で同じ容量のプールを使うと、列に割り当てた20枠のうち5枠が未使用で、残り12枠はどの列にも割り当てていません。<strong>この12枠は、別のリクエストに渡せる3つの空きブロック</strong>です。Aの最終ブロックに残った3枠はAに割り当て済みで、同じようには渡せません。プール全体を先に確保する実装では、この差がそのままプロセスのGPUメモリ使用量の差になるわけではありません。</p><p>この例のように、先頭から詰めて必要時だけ割り当てると、端数は各列の最終ブロックだけに残り、4枠のブロックなら最大3枠です。ブロックを小さくすると端数は減らせますが、ブロック表の項目が増え、GPUがまとめて読む単位も変わります。4という数字は説明用です。<a href="https://arxiv.org/html/2309.06180#S7.SS2" target="_blank" rel="noreferrer">Kwonらの原論文 §4.3・§7.2</a></p><h2 id="トークンの位置からブロック表を引く" tabindex="-1">トークンの位置からブロック表を引く <a class="header-anchor" href="#トークンの位置からブロック表を引く" aria-label="Permalink to &quot;トークンの位置からブロック表を引く&quot;">​</a></h2><p>列の中の順番を<strong>論理トークン位置</strong>と呼び、ここでは0から数えます。位置を4で割った商が論理ブロック番号、余りがブロック内の位置（オフセット）です。<strong>ブロック表</strong>は、各列の論理ブロック番号に対し、プール内の<strong>物理ブロック番号</strong>を記録します。例えばAの表が 6・4・1、Bの表が 2・7 なら、論理的に隣り合うブロックを離れた場所に置けます。<a href="https://arxiv.org/html/2309.06180#S4.SS1" target="_blank" rel="noreferrer">Kwonらの原論文 §4.1–4.3</a></p>',12),t("figure",{style:{margin:"1rem 0"}},[t("div",{role:"img","aria-label":"Aの論理トークン位置6を4で割ると商1、余り2。Aのブロック表は論理0、1、2に対して物理6、4、1を指すので、位置6のKVは物理ブロック4のオフセット2にある。",style:{display:"grid",gap:"0.4rem","max-width":"25rem"}},[t("strong",null,"① Aの論理トークン位置 6"),t("span",null,"↓ 4で割ると、論理ブロック 1・オフセット 2"),t("strong",null,"② Aのブロック表"),t("div",{style:{display:"grid","grid-template-columns":"7em repeat(3, minmax(0, 1fr))",gap:"0.3rem","text-align":"center"}},[t("span",{style:{"text-align":"left"}},"論理番号"),t("span",null,"0"),t("strong",null,"1"),t("span",null,"2"),t("span",{style:{"text-align":"left"}},"物理番号"),t("span",{style:{border:"1px solid var(--vp-c-divider)","border-radius":"4px"}},"6"),t("strong",{style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},"4"),t("span",{style:{border:"1px solid var(--vp-c-divider)","border-radius":"4px"}},"1")]),t("span",null,"↓ 物理番号を引き、オフセット 2 をそのまま使う"),t("strong",null,"③ 物理ブロック 4 の中"),t("div",{style:{display:"grid","grid-template-columns":"7em repeat(4, minmax(0, 1fr))",gap:"0.3rem","text-align":"center"}},[t("span",{style:{"text-align":"left"}},"オフセット"),t("span",null,"0"),t("span",null,"1"),t("strong",{style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},"2"),t("span",null,"3")])]),t("figcaption",{style:{"font-size":"0.875rem","margin-top":"0.5rem"}},"Aの7個目のトークンのKVは、物理ブロック4の3枠目にある。ブロック番号の変換で、オフセットは変わらない。")],-1),a('<p>Attentionを計算するGPUカーネルは、ブロック表を使って必要なKとVを読みます。どのKVが列のどの位置に対応するかはブロック表で決まり、最終ブロックでも有効な位置だけを使います。全位置を参照するAttentionなら、ブロックをまたいで参照範囲全体で正規化します。KVを列ごとの連続バッファに並べ直してから計算する必要がなくなります。<a href="https://arxiv.org/html/2309.06180#S4.SS1" target="_blank" rel="noreferrer">Kwonらの原論文 §4.1・§5.1</a></p><h2 id="終わった列のブロックを別の列に渡す" tabindex="-1">終わった列のブロックを別の列に渡す <a class="header-anchor" href="#終わった列のブロックを別の列に渡す" aria-label="Permalink to &quot;終わった列のブロックを別の列に渡す&quot;">​</a></h2><p>Aが先に終了すると、共有している相手がいないこの例では、Aの物理ブロック6・4・1をプールへ返せます。Bは最終ブロックの残り2枠を埋めたあと、9個目のKVを書くために次のブロックが必要になります。空きリストから4を取ると、Bの表は 2・7・4 になります。Bの既存のKVはそのまま参照でき、4にはBの新しい位置のKVを書きます。返すのは同じプール内の空き枠で、GPUへのメモリ確保を毎回やり直す処理とは区別します。<a href="https://arxiv.org/html/2309.06180#S4.SS3" target="_blank" rel="noreferrer">Kwonらの原論文 §4.2–4.3</a></p><h2 id="対応する実装では、同じ内容を共有し、書くときに分けられる" tabindex="-1">対応する実装では、同じ内容を共有し、書くときに分けられる <a class="header-anchor" href="#対応する実装では、同じ内容を共有し、書くときに分けられる" aria-label="Permalink to &quot;対応する実装では、同じ内容を共有し、書くときに分けられる&quot;">​</a></h2><p>原論文のvLLMでは、同じプロンプトから生成を2列に分岐するとき、同じ物理ブロックを両方の表から指せます。別の例として、共通の先頭が6トークンで、ブロックに4個入る場合を考えます。最初のブロックは満杯です。2番目には共通の2個と空き2枠があるため、そのまま両方が空きへ書くと、異なる続きを同じ枠に置くことになります。</p><p>片方が追記しようとしたとき、まだ別の列もそのブロックを参照していれば、新しい枠に既存のKVをコピーし、自分の表だけを付け替えてから書き込みます。これが<strong>コピーオンライト</strong>（copy-on-write、COW）です。満杯の共通ブロックを読み続けるだけならコピーは不要で、次のブロックを別々に割り当てられます。列が終了したときも、共有中のブロックは他の列のために残し、参照がなくなったものを再割り当てできる状態にします。<a href="https://arxiv.org/html/2309.06180#S4.SS4" target="_blank" rel="noreferrer">Kwonらの原論文 §4.4</a></p><p>別リクエストの先頭を再利用する方式には、満杯のブロックだけを対象にする実装もあります。たとえばvLLM v0.12.0のV1向けAutomatic Prefix Caching資料では、先行部分のハッシュ、ブロック内のトークン、必要に応じた付加情報から再利用するブロックを探します。参照が0になったブロックの内容が、再割り当てなどで追い出されるまでキャッシュに残ることもあります。原論文の分岐で部分ブロックを共有する例と、この方式の再利用単位は区別します。<a href="https://docs.vllm.ai/en/v0.12.0/design/prefix_caching/" target="_blank" rel="noreferrer">vLLM v0.12.0の設計資料</a></p><h2 id="osのページングとの共通点と違い" tabindex="-1">OSのページングとの共通点と違い <a class="header-anchor" href="#osのページングとの共通点と違い" aria-label="Permalink to &quot;OSのページングとの共通点と違い&quot;">​</a></h2><p><a href="/study/os/virtual-memory.html">仮想メモリ</a>のページングでも、連続する論理上の範囲を固定サイズに分け、表を介して離れた物理領域へ対応付けます。ページ番号を変換してページ内のオフセットを使う点が、図のブロック表と似ています。共有やコピーオンライトの考え方も共通しています。<a href="https://docs.kernel.org/mm/page_tables.html" target="_blank" rel="noreferrer">Linuxカーネルのページ表解説</a> · <a href="https://arxiv.org/html/2309.06180#S4.SS2" target="_blank" rel="noreferrer">Kwonらの原論文 §4.2–4.4</a></p><table tabindex="0"><thead><tr><th>観点</th><th>CPU側のOSページング</th><th>PagedAttentionでのKV管理</th></tr></thead><tbody><tr><td>対応付けるもの</td><td>プロセスの仮想アドレスのページ番号から物理ページへ</td><td>列の論理ブロック番号からGPU上のKVプール内の番号へ</td></tr><tr><td>表を管理し、参照する側</td><td>OSがページ表を管理し、CPUのメモリ管理機構が参照する</td><td>推論エンジンがブロック表を管理し、Attentionカーネルが参照する</td></tr><tr><td>いつ準備するか</td><td>例えば必要なページが使えなければ、ページフォルトをOSが処理する</td><td>書き込む位置が増えると分かった時点で、実行する前に必要なKVブロックを割り当てる</td></tr></tbody></table><p>ここでいう物理ブロック番号はプール内の番号です。実際のGPUメモリのアドレス変換とは別の段で使われます。最初の比較でいう連続予約はKVバッファの枠の取り置きで、Windowsなどが提供する仮想アドレスだけの予約とは区別します。<a href="https://docs.kernel.org/mm/page_tables.html" target="_blank" rel="noreferrer">Linuxカーネルのページ表解説</a> · <a href="https://arxiv.org/html/2309.06180#S4.SS2" target="_blank" rel="noreferrer">Kwonらの原論文 §3.1・§4.2–4.3</a></p><h2 id="同じメモリで、同時に処理できる列を増やす" tabindex="-1">同じメモリで、同時に処理できる列を増やす <a class="header-anchor" href="#同じメモリで、同時に処理できる列を増やす" aria-label="Permalink to &quot;同じメモリで、同時に処理できる列を増やす&quot;">​</a></h2><p>KVのために取り置く枠を減らせると、同じGPUメモリの予算でより多くの列を同じ実行単位（バッチ）に入れやすくなります。短い列が終わった後の空きに別の列を入れるには、実行する列を選び直せるスケジューラーも必要です。処理できる列が増えることと、1リクエストの次のトークンが速く届くことは別です。<a href="https://arxiv.org/html/2309.06180#S4.SS3" target="_blank" rel="noreferrer">Kwonらの原論文 §2.3・§4.3・§6</a> · <a href="/study/algorithms/llm-prefill-and-decode.html">LLM推論のprefillとdecode</a></p><p>ブロック表を引くことや、離れたブロックを読むことにも費用があります。元論文は、Attentionカーネル単体の比較で遅くなる条件も報告しています。狙いは、同じ履歴のKVを必要な場所から読んで同じAttentionを評価し、限られたメモリを複数の列で使いやすくすることです。生成品質を変える機能ではなく、配置が変わっても実装の演算順序や丸めまで一致するとは限りません。<a href="https://arxiv.org/html/2309.06180#S7.SS1" target="_blank" rel="noreferrer">Kwonらの原論文 §4.1・§7.1</a></p><h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2><ul><li>最大長の連続予約では、未使用の枠も各列に取り置きます。必要なブロックだけを割り当てると、残りのブロックを他の列に渡せます。</li><li>トークン位置を論理ブロックとオフセットに分け、列の表で物理ブロックを引きます。オフセットはそのまま使います。</li><li>最終ブロックの端数は残ります。列が終わり参照がなくなったブロックは、別の列へ再割り当てできます。</li><li>対応実装では同じKVを共有し、共有中のブロックに書くときだけ自分のコピーを作れます。</li><li>目的はGPUのKV用メモリを使いやすくし、同時に処理できる列を増やすことです。単一列の速度はカーネルや負荷にも左右されます。</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><details class="details custom-block"><summary>Aの9個目はどこにある？</summary><p>0始まりの位置は8です。4で割ると論理ブロック2、オフセット0です。Aの表から物理ブロック1の最初の枠を引きます。</p></details><details class="details custom-block"><summary>Aの一番後ろに空きが3枠あれば、Bはそれをすぐ借りられる？</summary><p>その3枠はAの最終ブロックの一部です。Bに回せるのは、プールで未割り当てになっているブロックです。</p></details><h2 id="検証範囲" tabindex="-1">検証範囲 <a class="header-anchor" href="#検証範囲" aria-label="Permalink to &quot;検証範囲&quot;">​</a></h2><p>2026年11月21日に原論文と公式文書を照合しました。WindowsのPython 3.12.4で表の枠数、ブロック表からの位置変換、Aの終了後のBへの再割り当てを検算しました。ブロック番号と長さは説明用です。vLLMの実行、実際のGPUメモリ量、速度、出力は測っていません。</p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/algorithms/kv-cache.html">KVキャッシュ</a> — 各層のKとVを何の計算に再利用するか、モデル構成から必要な容量をどう見積もるかを読む。</li><li><a href="/study/os/virtual-memory.html">仮想メモリとアドレス変換</a> — OSのページ表、ページフォルト、コピーオンライトとの共通点と違いを確認する。</li><li><a href="/study/algorithms/llm-prefill-and-decode.html">LLM推論のprefillとdecode</a> — 処理済みのトークンと生成した直後のトークンを分け、入力処理と生成を追う。</li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://arxiv.org/abs/2309.06180" target="_blank" rel="noreferrer">Woosuk Kwonほか — Efficient Memory Management for Large Language Model Serving with PagedAttention（SOSP 2023）</a> — 連続予約の課題、ブロック表、共有とCOW、速度の評価。</li><li><a href="https://docs.vllm.ai/en/v0.12.0/design/prefix_caching/" target="_blank" rel="noreferrer">vLLM v0.12.0 — Automatic Prefix Caching</a> — V1での満杯ブロックの再利用、参照数、空きキュー。</li><li><a href="https://docs.kernel.org/mm/page_tables.html" target="_blank" rel="noreferrer">Linux Kernel Documentation — Page Tables</a> — CPUのアドレス変換、ページ表、ページフォルト。</li></ul>',25)])])}const c=r(i,[["render",o]]);export{u as __pageData,c as default};
